  # D_n = (n-1)(D_{n-1}+D_{n-2}), O(n)
  D0, D1 = 1, 0       # D_0=1, D_1=0
  if n == 0: return D0
  for i in range(2, n+1):
    D0, D1 = D1, (i-1)*(D1+D0)
  return D1

